INSERT INTO `areatrigger_scripts` (`entry`, `ScriptName`) VALUES (5834, 'at_tott_lady_nazjar_event');
INSERT INTO `areatrigger_scripts` (`entry`, `ScriptName`) VALUES (5873, 'at_tott_commander_ulthok');
INSERT INTO `areatrigger_scripts` (`entry`, `ScriptName`) VALUES (6646, 'at_tott_ozumat');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39959, 0, 0, 'Armies of the depths, wash over our enemies as a tide of death!', 14, 0, 100, 0, 0, 18890, 'Lady Naz\'jar to Player'),
(39959, 1, 0, 'Meddlesome gnats! You think us defeated so easily?', 14, 0, 100, 0, 0, 18891, 'Lady Naz\'jar to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40586, 0, 0, 'You have interfered with our plans for the last time, mortals!', 14, 0, 100, 0, 0, 18886, 'Lady Naz\'jar - Aggro'),
(40586, 1, 0, 'Depths take you!', 14, 0, 100, 0, 0, 18887, 'Lady Naz\'jar - Slay'),
(40586, 1, 1, 'The Abyss awaits!', 14, 0, 0, 0, 0, 18888, 'VO_TT_Nazjar_Event03'),
(40586, 2, 0, 'Take arms, minions! Rise from the icy depths!', 14, 0, 100, 0, 0, 18892, 'Lady Naz\'jar - Summon Adds 1'),
(40586, 2, 1, 'Destroy these intruders! Leave them for the great dark beyond!', 14, 0, 100, 0, 0, 18893, 'Lady Naz\'jar - Summon Adds 2'),
(40586, 3, 0, 'Ulthok, stop them...', 14, 0, 100, 0, 0, 18889, 'Lady Naz\'jar - Death'),
(40586, 4, 0, 'Destroy these intruders! Leave them for the great dark beyond!', 14, 0, 0, 0, 0, 18893, 'VO_TT_Nazjar_Event08');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40765, 0, 0, 'Iilth vwah, uhn\'agth fhssh za.', 14, 0, 100, 0, 0, 18543, 'Commander Ulthok - Aggro'),
(40765, 1, 0, 'Where one falls, many shall take its place...', 15, 0, 100, 0, 0, 0, 'Commander Ulthok - Aggro Whisper'),
(40765, 2, 0, 'Gul\'kafh an\'shel.', 14, 0, 100, 0, 0, 18544, 'Commander Ulthok - Slay'),
(40765, 3, 0, 'Gaze into the void.', 15, 0, 100, 0, 0, 0, 'Commander Ulthok - Slay Whisper'),
(40765, 4, 0, 'Ywaq maq oou.', 14, 0, 100, 0, 0, 18542, 'Commander Ulthok - Death'),
(40765, 5, 0, 'They do not die.', 15, 0, 100, 0, 0, 0, 'Commander Ulthok to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40788, 0, 0, 'A new host must be found.', 14, 0, 100, 0, 0, 18860, 'Mindbender Ghur\'sha to Erunak Stonespeaker'),
(40788, 1, 0, 'Is. This. Reality?', 14, 0, 100, 0, 0, 18867, 'Mindbender Ghur\'sha'),
(40788, 1, 1, 'Only your memory remains...', 14, 0, 0, 0, 0, 18862, 'VO_TT_Mindbender_Event03'),
(40788, 2, 0, 'They are outside the cycle...', 14, 0, 100, 0, 0, 18863, 'Mindbender Ghur\'sha to Player'),
(40788, 3, 0, 'There is only Ghur\'sha.', 14, 0, 0, 0, 0, 18864, 'VO_TT_Mindbender_Event05'),
(40788, 3, 1, 'Give in...', 14, 0, 0, 0, 0, 18865, 'VO_TT_Mindbender_Event06'),
(40788, 3, 2, 'Who are your allies?', 14, 0, 0, 0, 0, 18866, 'VO_TT_Mindbender_Event07'),
(40788, 4, 0, 'Is. This. Reality?', 14, 0, 0, 0, 0, 18867, 'VO_TT_Mindbender_Event08');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40792, 0, 0, 'Ahh - my fearless assistants, I assume.', 14, 0, 100, 0, 0, 19469, 'Neptulon - Intro 1'),
(40792, 1, 0, 'You may yet regret your presence here.', 14, 0, 100, 0, 0, 19470, 'Neptulon - Intro 2'),
(40792, 2, 0, 'As I purify these waters, the servants of filth will surely be stirred. Beware!', 14, 0, 100, 0, 0, 19471, 'Neptulon - Purify Waters 1'),
(40792, 3, 0, 'Patience, guests. The waters are nearly cleansed.', 14, 0, 100, 0, 0, 19475, 'Neptulon - Purify Waters 2'),
(40792, 4, 0, 'The beast has returned! It must not pollute my waters!', 14, 0, 100, 0, 0, 19476, 'Neptulon to Player'),
(40792, 5, 0, 'Augh... Their filthiness stains me!', 14, 0, 100, 0, 0, 19472, 'Neptulon to Player'),
(40792, 6, 0, 'My waters are cleansed! Drink in their power!', 14, 0, 100, 0, 0, 19478, 'Neptulon to Player'),
(40792, 7, 0, 'Behold the power of pure water!', 14, 0, 100, 0, 0, 19477, 'Neptulon to Player'),
(40792, 8, 0, 'Ozumat is vulnerable, strike now!', 41, 0, 100, 0, 0, 19477, 'Neptulon to Player'),
(40792, 9, 0, 'My waters are cleansed! Drink in their power!', 14, 0, 0, 0, 0, 19478, 'VO_TT_Neptulon_Fight07'),
(40792, 10, 0, 'Your kind... cannot be... trusted.', 14, 0, 0, 0, 0, 19479, 'VO_TT_Neptulon_Fight08'),
(40792, 11, 0, 'You are unworthy of my domain...', 14, 0, 0, 0, 0, 19480, 'VO_TT_Neptulon_Fight09'),
(40792, 11, 1, 'My attention... was wasted on you...', 14, 0, 0, 0, 0, 19481, 'VO_TT_Neptulon_Fight10'),
(40792, 12, 0, 'My realm has at last been cleansed of the vile filth.', 14, 0, 0, 0, 0, 19482, 'VO_TT_Neptulon_Fight11'),
(40792, 13, 0, 'You are free to take your leave.', 14, 0, 0, 0, 0, 19483, 'VO_TT_Neptulon_Fight12');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40825, 0, 0, 'I thank you, my friends. Forgive me. I... I have grown too weak to be of any assistance.', 14, 0, 100, 0, 0, 18662, 'Erunak Stonespeaker'),
(40825, 1, 0, 'I am... weary. You must carry on without me. I shall take my leave once my strength has returned.', 14, 0, 100, 0, 0, 18664, 'Erunak Stonespeaker to Player');
