INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43873, 0, 0, 'The wind abruptly shifts direction at %s\' command!', 41, 0, 100, 0, 0, 0, 'Altairus - Announce Call the Wind'),
(43873, 1, 0, '%s senses $n\'s cowardice and unleashes a blast of lightning!', 16, 0, 100, 0, 0, 0, 'Altairus - Announce Lightning Blast');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43875, 0, 0, 'YOU tread upon the sacrosanct! Mortals have no place amidst the clouds.', 14, 0, 100, 0, 0, 20867, 'Asaad to Player'),
(43875, 1, 0, 'Al\'Akir, your servant calls for aid!', 14, 0, 100, 0, 0, 20869, 'Asaad'),
(43875, 2, 0, '%s conjures a temporary grounding field!', 41, 0, 100, 0, 0, 0, 'Asaad'),
(43875, 3, 0, 'The winds take me!', 14, 0, 100, 0, 0, 20870, 'Asaad to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43878, 0, 0, 'Filthy beasts! Your presence in Skywall will not be tolerated!', 14, 0, 100, 0, 0, 20876, 'Grandvizier Ertan - Aggro'),
(43878, 1, 0, '%s retracts her cyclone shield!', 41, 0, 100, 0, 0, 0, 'Grandvizier Ertan - Announce Storms Edge');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(45704, 0, 0, '%s realizes it\'s been spotted and quickly plays dead!', 16, 0, 100, 0, 0, 0, 'Lurking Tempest');
