INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39625, 0, 0, 'Cover the rear! Alexstrasza\'s brood decimate our ranks!', 14, 0, 100, 0, 0, 18537, 'General Umbriss'),
(39625, 0, 1, 'Reinforce the front! We are being invaded!', 14, 0, 100, 0, 0, 18536, 'General Umbriss'),
(39625, 1, 0, 'A million more await my orders. What chance do you have?', 14, 0, 100, 0, 0, 18530, 'General Umbriss to Player'),
(39625, 1, 1, 'Messy...', 14, 0, 100, 0, 0, 18532, 'VO_GB_Umbriss_Event03'),
(39625, 2, 0, 'Attack you cowardly vermin!', 14, 0, 100, 0, 0, 18535, 'General Umbriss'),
(39625, 2, 1, 'Vermin, your dinner awaits!', 14, 0, 100, 0, 0, 18531, 'General Umbriss'),
(39625, 3, 0, 'Messy...', 14, 0, 100, 0, 0, 18532, 'General Umbriss'),
(39625, 4, 0, '|TInterface\\Icons\\ability_warrior_charge.blp:20|tGeneral Umbriss sets his eyes on |cFFFF0000$n|r and begins to cast |cFFFF0000|Hspell:74670|h[Blitz]|h|r!', 41, 0, 100, 0, 0, 0, 'General Umbriss to Player'),
(39625, 5, 0, '|TInterface\\Icons\\spell_nature_earthquake.blp:20|tGeneral Umbriss begins to cast |cFFFF0000|Hspell:74634|h[Ground Siege]|h|r!', 41, 0, 100, 0, 0, 0, 'General Umbriss to Ground Siege'),
(39625, 6, 0, '%s goes into a frenzy!', 41, 0, 100, 0, 0, 0, 'General Umbriss');
