INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40177, 0, 0, 'NO! Throngus get whipped again if he no finish!', 14, 0, 100, 0, 0, 18943, 'Forgemaster Throngus - Say Aggro'),
(40177, 1, 0, 'You not get through defenses!', 14, 0, 100, 0, 0, 18947, 'Forgemaster Throngus - Say Personal Phalanx'),
(40177, 1, 1, 'You break easy!', 14, 0, 100, 0, 0, 18945, 'VO_GB_Throngus_Event03'),
(40177, 2, 0, 'Oh, this gonna HURT!', 14, 0, 100, 53, 0, 18949, 'Forgemaster Throngus - Say Mace'),
(40177, 3, 0, 'Throngus SLICE you up!', 14, 0, 100, 0, 0, 18948, 'Forgemaster Throngus - Say Swords'),
(40177, 4, 0, '|TInterface\\Icons\\inv_shield_76.blp:20|t%s equips his |cFFFF0000Shield|r and gains |cFFFF0000|Hspell:74908|h[Personal Phalanx]|h|r!', 41, 0, 100, 0, 0, 0, 'Forgemaster Throngus - Announce Personal Phalanx'),
(40177, 5, 0, '|TInterface\\Icons\\inv_mace_15.blp:20|t%s equips his |cFFFF0000Mace|r and is |cFFFF0000|Hspell:75007|h[Encumbered]|h|r!', 41, 0, 100, 53, 0, 0, 'Forgemaster Throngus - Announce Mace'),
(40177, 6, 0, '|TInterface\\Icons\\ability_dualwield.blp:20|t%s equips his |cFFFF0000Swords|r and gains |cFFFF0000|Hspell:74981|h[Dual Blades]|h|r!', 41, 0, 100, 0, 0, 0, 'Forgemaster Throngus - Announce Swords'),
(40177, 7, 0, '$n is impaled!', 41, 0, 100, 0, 0, 0, 'Forgemaster Throngus - Announce Impaled'),
(40177, 8, 0, 'Throngus use your corpse on body. Somewhere...', 14, 0, 100, 0, 0, 18944, 'Forgemaster Throngus - Slay 1'),
(40177, 8, 1, 'You break easy!', 14, 0, 100, 0, 0, 18945, 'Forgemaster Throngus - Slay 2'),
(40177, 9, 0, 'Death... Good choice. Not best choice maybe, but better than fail and live.', 14, 0, 100, 0, 0, 18946, 'Forgemaster Throngus to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40319, 0, 0, 'I will burn you from the inside out!', 14, 0, 100, 0, 0, 18610, 'VO_GB_Drahga_Event01'),
(40319, 1, 0, 'I will burn you from the inside out!', 14, 0, 100, 0, 0, 18610, 'Drahga Shadowburner - Aggro'),
(40319, 2, 0, '|TInterface\\Icons\\spell_fire_elemental_totem.blp:20|t%s Summons an |cFFFF6F00|Hspell:75218|h[Invocation of Flame]|h|r!', 41, 0, 100, 0, 0, 0, 'Drahga Shadowburner - Announce Invocation'),
(40319, 3, 0, 'BY FIRE BE... BURNED!', 14, 0, 100, 0, 0, 18619, 'Drahga Shadowburner - Invocation 1'),
(40319, 3, 1, 'INCINERATE THEM, MINIONS!', 14, 0, 100, 0, 0, 18616, 'Drahga Shadowburner - Invocation 2'),
(40319, 4, 0, 'Dragon, you will do as I command! Catch me!', 14, 0, 100, 22, 0, 18621, 'Drahga Shadowburner - Valiona Intro'),
(40319, 4, 1, 'BY FIRE BE... BURNED!', 14, 0, 100, 0, 0, 18619, 'VO_GB_Drahga_Event06'),
(40319, 5, 0, 'You should have come better prepared!', 14, 0, 100, 0, 0, 18612, 'Drahga Shadowburner - Slay 1'),
(40319, 5, 1, 'An easy kill!', 14, 0, 100, 0, 0, 18611, 'Drahga Shadowburner - Slay 2'),
(40319, 6, 0, 'Valiona, finish them! Avenge me!', 14, 0, 100, 0, 0, 18614, 'Drahga Shadowburner - Death');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40320, 0, 0, 'If they do not kill you, I will do it myself!', 14, 0, 100, 0, 0, 18523, 'Valiona - Summoned'),
(40320, 1, 0, '|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s begins to cast |cFFFF0000|Hspell:90949|h[Devouring Flames]|h|r!', 41, 0, 100, 0, 0, 0, 'Valiona - Announce Devouring Flames'),
(40320, 2, 0, 'I will not die for you, Drahga.', 14, 0, 100, 0, 0, 18524, 'Valiona - Flee');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(40484, 0, 0, 'The darkest days are still ahead!', 14, 0, 100, 0, 0, 18638, 'Erudax - Aggro'),
(40484, 1, 0, '|TInterface\\Icons\\spell_shadow_shadowfury.blp:20|t%s begins to cast |cFFA043E7|Hspell:75694|h[Shadow Gale]|h|r!', 41, 0, 100, 0, 0, 0, 'Erudax - Announce Shadow Gale'),
(40484, 1, 1, 'Flesh for the offering.', 14, 0, 100, 0, 0, 18640, 'VO_GB_Erudax_Event03'),
(40484, 2, 0, 'F\'lakh ghet! The shadow\'s hunger cannot be sated!', 14, 0, 100, 0, 0, 18644, 'Erudax - Shadow Gale'),
(40484, 3, 0, 'Come, suffering... Enter, chaos!', 14, 0, 100, 0, 0, 18646, 'Erudax to Erudax'),
(40484, 4, 0, '%s summons a |cFFFF0000Faceless Guardian|r!', 41, 0, 100, 0, 0, 0, 'Erudax to Erudax'),
(40484, 5, 0, '|TInterface\\Icons\\spell_shadow_sacrificialshield.blp:20|t%s begins to cast |cFF006EFD|Hspell:75809|h[Shield of Nightmares]|h|r on the |cFF006EFDFaceless Corruptor|r!', 41, 0, 100, 0, 0, 0, 'Erudax - Shield of Nightmares'),
(40484, 6, 0, 'Flesh for the offering!', 14, 0, 100, 0, 0, 18640, 'Erudax - Slay 1'),
(40484, 6, 1, 'Ahahaha!', 16, 0, 100, 0, 0, 18639, 'Erudax - Slay 2'),
(40484, 7, 0, 'Ywaq maq oou; ywaq maq ssaggh. Yawq ma shg\'fhn.', 14, 0, 100, 0, 0, 18641, 'Erudax - Death');
