INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(43612, 0, 0, 'Begone infidels, you are not welcome here!', 14, 0, 100, 0, 0, 19735, 'High Prophet Barim'),
(43612, 1, 0, 'May peace find you now.', 14, 0, 100, 0, 0, 19738, 'High Prophet Barim'),
(43612, 1, 1, 'The heavens take you!', 14, 0, 100, 0, 0, 19736, 'High Prophet Barim'),
(43612, 2, 0, 'Kneel before me and repent!', 14, 0, 100, 0, 0, 19737, 'High Prophet Barim'),
(43612, 3, 0, 'Death is only the beginning!', 14, 0, 100, 0, 0, 19733, 'High Prophet Barim'),
(43612, 3, 1, 'The heavens take you!', 14, 0, 0, 0, 0, 19736, 'boss_high_prophet_barim - SAY_KILL_PLAYER 2');
