(44577, 0, 0, 'Invaders, you shall go no further!', 14, 0, 100, 0, 0, 0, 'General Husam to Player'),
(44577, 1, 0, 'Insolent rat!', 14, 0, 100, 0, 0, 0, 'General Husam to Player'),
(44577, 2, 0, 'Murkash!', 14, 0, 100, 0, 0, 0, 'General Husam'),
(44577, 3, 0, '|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s begins to cast |cFFFF0000|Hspell:83445|h[Shockwave]!|h|r', 41, 0, 100, 0, 0, 0, 'General Husam'),
