(49045, 1, 0, 'GAAAH! How you kill croc?!', 12, 0, 0, 53, 0, 0, 'Augh - Intro 2'),
(49045, 2, 0, 'Augh smart! Augh already steal treasure while you no looking!', 12, 0, 0, 1, 0, 0, 'Augh - Intro 3'),
(49045, 3, 0, 'Augh da boss! Oh yeah!', 12, 0, 0, 0, 0, 0, 'Augh Taunt'),
(49045, 4, 0, 'Augh steal your treasure. Uhn uhn uhnnn!', 12, 0, 0, 0, 0, 0, 'Augh Taunt'),
(49045, 5, 0, 'Who bad?! Augh bad!! Ugn!', 12, 0, 0, 0, 0, 0, 'Augh Taunt'),
(49045, 6, 0, 'Gwaaaaaaahhh!!!', 14, 0, 0, 53, 0, 0, 'boss_augh - AUGH_SAY_AAA');
